intro/main.js:
clip({ bars: 8, note: "psaltery over a drone, frame drum pulse; no kick yet (harp on its own track)" })

// drone pad
$: note("<[d2,a2,d3] [d2,a2,d3] [d2,a2,d3] [d2,bb2,eb3]>")
  .s("supersaw").detune(.15).attack(1.5).release(2).lpf(sine.range(500, 1400).slow(16))
  .gain(.28).room(.6).size(.9).orbit(2)

// psaltery bowed swell
$: note("<~ a4 ~ [bb4 a4]>").s("psaltery_bow").velocity(rand.range(.8, 1)).nudge(rand.range(0, .015)).slow(2).gain(.35).room(.7).orbit(2)

// frame drum pulse
$: s("framedrum ~ ~ framedrum ~ ~ framedrum ~").velocity(rand.range(.8, 1)).nudge(rand.range(0, .006)).gain(.55).room(.3)

fx/riser.js:
clip({ bars: 4, note: "timpani roll + snare roll, crescendo into a drop" })

// timpani roll, restruck louder each bar
$: s("timpani_roll").n(3).gain("<.4 .6 .8 1>").attack(.3).clip(1).room(.4).orbit(2)

// 909 snare roll, doubling each bar
$: s("<sd*4 sd*8 sd*16 [sd*16 sd*32]>").bank("RolandTR909")
  .gain(saw.slow(4).range(.1, .45)).hpf(saw.slow(4).range(200, 1200))

fx/fall.js:
clip({ bars: 2, note: "soft landing into the break: timpani rumble fading out" })

// soft low gong, no crash
_$: s("<gong ~>")

// timpani rumble fading out
// (a sample's gain is fixed at its start, so the fade is an envelope)
$: s("timpani_roll").n(3).slow(2).speed(.9).gain(.9).decay(3.5).sustain(0).room(.4).orbit(3)
